  for (const show of hits.slice(0, SEARCH_RESULT_ROWS)) {
    const row = rowElement(show, "li");
    row.setAttribute("role", "option");
    results.appendChild(row);
  }
  $("ssEmpty").hidden = hits.length > 0;
  $("ssPop").hidden = false;
  $("ssInput").setAttribute("aria-expanded", "true");
}

