/* The programme's drawer, opened. With the calendar carrying every constraint
 * the reader sets, nothing inside the drawer is needed to work it, so it opens
 * on the reader's own ask — and a case that asserts what is inside it has to
 * make that ask first. */
async function openDrawer(page) {
  await page.evaluate(() => {
    const drawer = document.getElementById("boardDrawer");
    if (!drawer.open) drawer.open = true;
  });
  await page.waitForTimeout(150);
  await settle(page);
}

/* Rest the pointer on a calendar card until its popup opens: the popup waits
 * for the pointer to rest, so a bare hover captures the calendar without it. */
async function openCard(page, block) {
  await (typeof block === "string" ? page.locator(block) : block).hover();
  await page.waitForSelector("#calPreview:not([hidden])");
  await settle(page);
}

