    await page.locator("#browseList .ss-star").first().click();
    await page.waitForSelector(".lane");
    await page.click("#ssInput");
    await page.waitForSelector("#ssResults .ss-row");
    const rows = page.locator("#ssResults .ss-row:not(.is-on)");
